-- PyDex Seed Data (Standard Library Definitions)
BEGIN TRANSACTION;
INSERT OR IGNORE INTO modules (id, name, description) VALUES (1, 'builtins', 'Python Built-in Functions');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (2, 'math', 'Python math standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (3, 'random', 'Python random standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (4, 'json', 'Python json standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (5, 'os', 'Python os standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (6, 'time', 'Python time standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (7, 're', 'Python re standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (8, 'shutil', 'Python shutil standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (9, 'csv', 'Python csv standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (10, 'hashlib', 'Python hashlib standard library');
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (1, 'abs', 1, 'The `abs()` function returns the non‑negative magnitude of its argument, whether it is an integer, float, complex number, or any object that defines an `__abs__` method.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (2, 'aiter', 1, '`aiter()` returns the asynchronous iterator of an asynchronous iterable by invoking its `__aiter__` method, providing a direct way to obtain an async iterator without supporting a two‑argument form.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (3, 'all', 1, 'The `all()` function checks an iterable and returns True only if every element evaluates to True (or if the iterable is empty), otherwise it returns False.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (4, 'anext', 1, '`anext()` asynchronously retrieves the next element from an async iterator, optionally returning a default value instead of raising StopAsyncIteration when the iterator is exhausted.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (5, 'any', 1, 'The `any()` function checks an iterable and returns True if at least one element evaluates as true, otherwise it returns False (including when the iterable is empty).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (6, 'ascii', 1, 'The ascii() function returns a printable string representation of an object like repr(), but escapes any non‑ASCII characters using \x, \u, or \U escape sequences.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (7, 'bin', 1, 'The `bin()` function returns a string representing an integer’s binary value, prefixed with “0b” (or “-0b” for negatives), and works with any object that defines an `__index__` method.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (8, 'bool', 1, 'The bool() function converts its argument to a Boolean value, returning False for falsey inputs or no argument and True otherwise.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (9, 'breakpoint', 1, 'It provides a simple way to invoke the current debugger (by default pdb.set_trace) at the call point, delegating to sys.breakpointhook() which can be customized or controlled via the PYTHONBREAKPOINT environment variable.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (10, 'bytearray', 1, '`bytearray()` creates a mutable sequence of bytes that can be initialized from a string (with encoding), an integer size (filled with zeros), a buffer, an iterable of integers 0‑255, or left empty.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (11, 'bytes', 1, 'The `bytes()` function creates an immutable sequence of integer values (0–255), converting given data (e.g., iterable, string, or integer) into a bytes object that behaves like a read‑only version of `bytearray`.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (12, 'callable', 1, 'The callable() function checks whether a given object can be invoked like a function, returning True if it is callable (including classes and objects with a __call__ method) and False otherwise.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (13, 'chr', 1, 'chr() converts an integer Unicode code point (0‑0x10FFFF) into the corresponding one‑character string, raising ValueError for out‑of‑range values.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (14, 'classmethod', 1, 'classmethod() converts a regular function into a method that receives the class itself as its first argument, allowing it to be invoked on the class or its instances and to operate with class-level data.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (15, 'compile', 1, 'The `compile()` function transforms a source string, byte string, or AST object into a code object (or AST) that can be executed with `exec()` or `eval()`, allowing specification of filename, mode, compiler flags, inheritance behavior, and optimization level, while handling errors for invalid syntax or resource limits.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (16, 'complex', 1, 'The `complex()` function converts a string or numeric value (or separate real and imaginary parts) into a Python complex number, handling various formats and falling back on object methods like `__complex__`, `__float__`, or `__index__` when needed.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (17, 'delattr', 1, 'delattr() removes a specified attribute from an object by name, acting like the statement del object.attribute.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (18, 'dict', 1, 'The `dict()` function constructs and returns a new dictionary object, optionally initializing it with key‑value pairs from another mapping, iterable of pairs, or keyword arguments.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (19, 'dir', 1, '`dir()` returns a sorted list of attribute names for the current local scope when called without arguments, or for a given object by using its `__dir__` method if defined or otherwise gathering names from its `__dict__`, type, and inheritance hierarchy.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (20, 'divmod', 1, '`divmod(a, b)` returns a two‑element tuple containing the integer quotient and the remainder of a divided by b, following the same rules as the // and % operators for both integer and floating‑point operands.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (21, 'enumerate', 1, 'enumerate() returns an iterator that yields pairs of an increasing index (starting from a given start value, default 0) and each element from the given iterable.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (22, 'eval', 1, 'The eval() function parses and evaluates a given Python expression string or code object within optional global and local namespaces, returning the resulting value while warning that executing untrusted code is insecure.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (23, 'exec', 1, 'exec() dynamically runs a string or code object as Python statements within optional global and local namespaces, returning None.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (24, 'filter', 1, 'The `filter()` function creates an iterator that yields only those items from a given iterable for which a provided function returns true (or, if the function is None, only the truthy items).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (25, 'float', 1, 'float() converts a given numeric value or suitably formatted string—optionally containing signs, whitespace, underscores, exponentials, “inf”, or “nan”—into a Python floating‑point number, defaulting to 0.0 when called without an argument.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (26, 'format', 1, 'The `format()` function returns a string representation of a value formatted according to a given format specification, defaulting to the same result as `str(value)` when the specification is empty.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (27, 'frozenset', 1, 'frozenset() creates an immutable set object that can be populated from an iterable, providing a hashable collection of unique elements.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (28, 'getattr', 1, 'getattr() returns the value of a specified attribute from an object, raising AttributeError if the attribute isn’t present unless a default value is provided.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (29, 'globals', 1, 'The globals() function returns a dictionary representing the current module’s global symbol table, reflecting the namespace that was established when the function was defined and staying constant regardless of where it is later called.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (30, 'hasattr', 1, 'hasattr() checks whether a given object possesses an attribute with a specified name, returning True if it exists and False otherwise.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (31, 'hash', 1, 'The Python `hash()` function returns an integer hash value for an object, enabling fast key comparison in dictionaries by ensuring that equal values (including different numeric types like 1 and 1.0) produce the same hash, with custom `__hash__` results truncated to the host machine’s pointer size.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (32, 'help', 1, 'The built‑in help() function launches Python’s interactive documentation system, displaying detailed help pages for modules, functions, classes, methods, keywords, or any object when called with or without an argument.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (33, 'hex', 1, 'hex() takes an integer (or an object defining __index__) and returns its value as a lowercase hexadecimal string prefixed with “0x”.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (34, 'id', 1, 'The built‑in id() function returns a unique, constant integer that identifies a specific object for the duration of its existence.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (35, 'input', 1, 'The `input()` function optionally displays a prompt, reads a line from standard input, strips the trailing newline, returns the resulting string, and raises EOFError if end‑of‑file is encountered.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (36, 'int', 1, 'int() converts a given number, string, bytes, or bytearray (optionally with a specified base) into an integer object, defaulting to 0 when called without arguments.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (37, 'isinstance', 1, '`isinstance()` checks whether a given object is an instance of a specified type (or any type in a tuple or Union), returning True if it matches and False otherwise.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (38, 'issubclass', 1, 'issubclass() returns True when a given class is the same as, directly or indirectly inherits from, or is virtually subclassed by the specified class(es) or Union Type, otherwise it raises a TypeError.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (39, 'iter', 1, 'The iter() function creates an iterator either from an iterable or sequence when called with one argument, or from a callable that repeatedly produces values until a specified sentinel value is returned, signaling termination.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (40, 'len', 1, 'The `len()` function returns the number of items in a sequence or collection, raising an OverflowError if the count exceeds `sys.maxsize`.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (41, 'list', 1, 'The list() callable creates a new mutable sequence (list) from an iterable, converting the given iterable’s elements into a list object.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (42, 'locals', 1, '`locals()` returns a mapping of the current local variable names to their values, allowing inspection (and in some scopes, modification) of the local symbol table.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (43, 'map', 1, '`map()` returns an iterator that applies a given function to each element (or parallel elements from multiple iterables) of the provided iterable(s), producing the function’s results sequentially.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (44, 'max', 1, 'The `max()` function returns the greatest element from a single iterable or the greatest of multiple given arguments, optionally using a key function for ordering and a default value if the iterable is empty.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (45, 'memoryview', 1, '`memoryview()` creates a lightweight object that provides read‑ and/or write‑access to the underlying buffer of a bytes‑like object without copying its data.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (46, 'min', 1, 'The `min()` function returns the smallest element from a single iterable or the smallest of multiple given arguments, optionally using a key function for ordering and a default value to return when the iterable is empty.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (47, 'next', 1, 'The `next()` function obtains the subsequent element from an iterator by invoking its `__next__()` method, returning a provided default value if the iterator is exhausted, otherwise raising `StopIteration`.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (48, 'object', 1, 'The `object()` function creates a minimal, featureless instance of Python’s ultimate base class, which has no arguments, no `__dict__`, and provides only the fundamental methods common to all objects.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (49, 'oct', 1, 'The oct() function returns a string representing an integer’s value in octal notation, prefixed with “0o” (or a leading minus sign for negative numbers).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (50, 'open', 1, 'The built‑in `open()` function opens a file (or file descriptor) with a specified mode, encoding, buffering, and other optional parameters, returning a corresponding file object for reading, writing, or both, and raises an OSError if the operation fails.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (51, 'ord', 1, 'The `ord()` function returns the integer Unicode code point of a single-character string or the numeric byte value of a one‑byte bytes/bytearray object.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (52, 'pow', 1, 'The Python `pow()` function computes the value of a base raised to an exponent, optionally performing modular exponentiation efficiently when a modulus argument is provided.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (53, 'print', 1, 'The `print()` function outputs the string representations of given objects to a text stream (defaulting to standard output), separating them with a specified delimiter and ending with a specified terminator, optionally flushing the stream.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (54, 'property', 1, 'The `property()` function creates a descriptor that lets you define getter, setter, and deleter methods (and an optional docstring) for a managed attribute, enabling attribute access to invoke custom functions.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (55, 'getter', 1, 'I cannot provide a summary because the code or description of the `getter()` function was not included.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (56, 'setter', 1, 'The `setter()` function assigns a new value to a specified attribute of an object, optionally handling validation or side‑effects before updating the attribute.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (57, 'deleter', 1, 'The `deleter()` method creates a new property object identical to the original but with its `fdel` accessor replaced by the function you decorate, allowing deletion of the underlying attribute.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (58, '__name__', 1, '`__name__` is a special attribute that stores the identifier of a module or class (or the name of the currently executing script), allowing code to detect whether it is being run directly or imported and enabling runtime introspection or dynamic renaming.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (59, 'range', 1, 'The range() construct creates an immutable sequence of numbers defined by a start, stop, and optional step, allowing efficient iteration without storing all values in memory.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (60, 'repr', 1, 'repr() returns a string that gives an unambiguous, often eval‑able, printable representation of an object, falling back to a generic description if a precise one isn’t available.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (61, 'reversed', 1, 'The `reversed()` function returns an iterator that yields the elements of a sequence or any object implementing `__reversed__` (or supporting the sequence protocol via `__len__` and integer-indexed `__getitem__`) in reverse order.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (62, 'round', 1, 'The `round()` function returns a number rounded to a specified number of decimal places (or to the nearest integer if no precision is given), using “bankers rounding” where ties are broken by choosing the even result.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (63, 'set', 1, 'The built-in `set()` function creates and returns a new mutable set object, optionally initializing it with unique elements drawn from a given iterable.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (64, 'setattr', 1, 'setattr() assigns a given value to a specified attribute (existing or new) of an object, using the attribute’s name as a string, effectively performing the same operation as the dot notation assignment.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (65, 'slice', 1, 'The slice() function creates a slice object that encapsulates start, stop, and step indices (defaulting to None) for use in slicing operations and compatible with NumPy and other libraries.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (66, 'start', 1, 'The `start()` function initializes the object''s read‑only attributes using the provided arguments (or defaults), serving solely as a setup for NumPy and related third‑party package operations.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (67, 'sorted', 1, 'The built‑in sorted() function returns a new list containing the elements of any iterable arranged in order, optionally using a key function to extract comparison values and a reverse flag to invert the sort, while preserving the original order of equal items.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (68, 'staticmethod', 1, '`staticmethod()` decorates a function to become a class-level method that receives no implicit instance or class argument, allowing it to be called on the class or its instances like a regular function.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (69, 'str', 1, 'The str() function converts any given object into its string representation, returning the resulting text as a standard Python string.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (70, 'sum', 1, 'The sum() function adds a specified start value to each element of an iterable (typically numeric) from left to right and returns the total.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (71, 'super', 1, 'super() returns a proxy that searches the method‑resolution order after a specified class (or the current class when used without arguments) to delegate calls to inherited or sibling methods, enabling explicit parent method access and cooperative multiple inheritance.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (72, 'tuple', 1, 'The `tuple()` constructor creates an immutable sequence object by converting an iterable (or producing an empty tuple when called without arguments).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (73, 'type', 1, 'The built‑in `type()` returns an object’s type when called with one argument and dynamically creates a new class (specifying its name, base classes, and attribute dictionary) when called with three arguments.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (74, 'vars', 1, 'The `vars()` function returns an object''s `__dict__` mapping (or, when called with no argument, the current local symbol table), raising a TypeError if the supplied object lacks a `__dict__`.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (75, 'zip', 1, 'zip() lazily combines multiple iterables element‑wise into tuples, stopping at the shortest iterable unless strict=True is used to enforce equal lengths.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (76, '__import__', 1, '`__import__()` is a low‑level built‑in that the import statement calls to load a module (optionally using package context, from‑list, and relative‑import level) and return either the top‑level package or the requested submodule.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (77, 'acos', 2, 'Return the arc cosine (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (78, 'acosh', 2, 'Return the inverse hyperbolic cosine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (79, 'asin', 2, 'Return the arc sine (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (80, 'asinh', 2, 'Return the inverse hyperbolic sine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (81, 'atan', 2, 'Return the arc tangent (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (82, 'atan2', 2, 'Return the arc tangent (measured in radians) of y/x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (83, 'atanh', 2, 'Return the inverse hyperbolic tangent of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (84, 'cbrt', 2, 'Return the cube root of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (85, 'ceil', 2, 'Return the ceiling of x as an Integral.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (86, 'comb', 2, 'Number of ways to choose k items from n items without repetition and without order.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (87, 'copysign', 2, 'Return a float with the magnitude (absolute value) of x but the sign of y.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (88, 'cos', 2, 'Return the cosine of x (measured in radians).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (89, 'cosh', 2, 'Return the hyperbolic cosine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (90, 'degrees', 2, 'Convert angle x from radians to degrees.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (91, 'dist', 2, 'Return the Euclidean distance between two points p and q.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (92, 'erf', 2, 'Error function at x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (93, 'erfc', 2, 'Complementary error function at x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (94, 'exp', 2, 'Return e raised to the power of x.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (95, 'exp2', 2, 'Return 2 raised to the power of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (96, 'expm1', 2, 'Return exp(x)-1.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (97, 'fabs', 2, 'Return the absolute value of the float x.', NULL, 0, 0);
